<?php defined('ALTUMCODE') || die();
$t='fcc_top_t';$h='fcc_partner_h';$top=$data->top??null;
\Altum\Event::add_content('<link rel="stylesheet" href="'.ASSETS_FULL_URL.'css/fcc-top.css?v='.filemtime(ASSETS_PATH.'css/fcc-top.css').'">','head');
?>
<section class="ft-hero"><div><span class="fp-eyebrow">FCC · PRO</span><h1><?= $h($t('title')) ?></h1><p><?= $h($t('intro')) ?></p></div><a class="fp-button fp-button-light" href="<?= url('partner/settings#fcc-top-settings') ?>"><?= $h($t('settings')) ?></a></section>
<?php if(!$top): ?><p class="fp-message" role="status"><?= $h($t('unavailable')) ?></p><?php return;endif ?>
